create extension if not exists pgcrypto;
create table if not exists public.courses (id text primary key, name text not null, price_twd integer not null check (price_twd > 0), active boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete restrict, course_id text not null references public.courses(id) on delete restrict, merchant_order_no text not null unique, amount_twd integer not null check (amount_twd > 0), status text not null default 'pending' check (status in ('pending','paid','failed','refunded','revoked')), trade_no text, paid_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.course_entitlements (user_id uuid not null references auth.users(id) on delete cascade, course_id text not null references public.courses(id) on delete cascade, order_id uuid not null references public.orders(id) on delete restrict, status text not null default 'active' check (status in ('active','revoked')), starts_at timestamptz not null, expires_at timestamptz not null, primary key (user_id, course_id), check (expires_at > starts_at));
create table if not exists public.course_lessons (id uuid primary key default gen_random_uuid(), course_id text not null references public.courses(id) on delete cascade, title text not null, video_path text, sort_order integer not null default 0, active boolean not null default false, created_at timestamptz not null default now());
create index if not exists orders_user_created_idx on public.orders(user_id, created_at desc);
create index if not exists orders_course_idx on public.orders(course_id);
create index if not exists entitlements_expiry_idx on public.course_entitlements(user_id, course_id, expires_at);
create index if not exists entitlements_course_idx on public.course_entitlements(course_id);
create index if not exists entitlements_order_idx on public.course_entitlements(order_id);
create index if not exists lessons_course_sort_idx on public.course_lessons(course_id, sort_order);
alter table public.courses enable row level security;
alter table public.orders enable row level security;
alter table public.course_entitlements enable row level security;
alter table public.course_lessons enable row level security;
drop policy if exists "active courses are public" on public.courses;
create policy "active courses are public" on public.courses for select to anon, authenticated using (active);
drop policy if exists "users read own orders" on public.orders;
create policy "users read own orders" on public.orders for select to authenticated using ((select auth.uid()) = user_id);
drop policy if exists "users read own entitlements" on public.course_entitlements;
create policy "users read own entitlements" on public.course_entitlements for select to authenticated using ((select auth.uid()) = user_id);
drop policy if exists "entitled users read lessons" on public.course_lessons;
create policy "entitled users read lessons" on public.course_lessons for select to authenticated using (active and exists (select 1 from public.course_entitlements e where e.user_id = (select auth.uid()) and e.course_id = course_lessons.course_id and e.status = 'active' and e.expires_at > now()));
insert into public.courses(id,name,price_twd,active) values ('codex-basics','Codex 基礎使用',2000,true) on conflict (id) do update set name=excluded.name,price_twd=excluded.price_twd;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('course-videos','course-videos',false,1073741824,array['video/mp4','video/webm']) on conflict (id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
